import{_ as a,o as t,c as r,a0 as o}from"./chunks/framework.DZqO77tS.js";const m=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/getting-started.md","filePath":"en/docs/getting-started.md"}'),i={name:"en/docs/getting-started.md"};function n(s,e,l,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Welcome! This page gets you to a <strong>first success</strong> in about 15–20 minutes.</p><h2 id="you-will-need" tabindex="-1">You will need <a class="header-anchor" href="#you-will-need" aria-label="Permalink to &quot;You will need&quot;">​</a></h2><ul><li>An EcoCONNECT board (main board)</li><li>A USB cable that fits your board</li><li>A computer (Windows, macOS, or Linux)</li></ul><p>Optional: a notebook for observations.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-check-the-board" tabindex="-1">1. Check the board <a class="header-anchor" href="#_1-check-the-board" aria-label="Permalink to &quot;1. Check the board&quot;">​</a></h3><p>Look over the board once. Find:</p><ul><li>The USB connector</li><li>The main chip area</li><li>Any clearly labeled sensor connectors</li></ul><p>If something looks damaged, stop and ask a teacher or mentor for help.</p><h3 id="_2-connect-power" tabindex="-1">2. Connect power <a class="header-anchor" href="#_2-connect-power" aria-label="Permalink to &quot;2. Connect power&quot;">​</a></h3><ol><li>Plug the USB cable into the board.</li><li>Plug the other end into your computer.</li><li>Look for a power indicator (LED or similar) if your board has one.</li></ol><h3 id="_3-load-the-ready-made-firmware-beginner-path" tabindex="-1">3. Load the ready-made firmware (beginner path) <a class="header-anchor" href="#_3-load-the-ready-made-firmware-beginner-path" aria-label="Permalink to &quot;3. Load the ready-made firmware (beginner path)&quot;">​</a></h3><p>EcoCONNECT includes a <strong>ready-to-use firmware image</strong> so you do not need to write code first.</p><ol><li>Open the repository’s <code>firmware/pico2/release/</code> folder.</li><li>Follow the short README in <code>firmware/pico2/</code> for how to copy the <code>.uf2</code> image to the Raspberry Pi Pico.</li><li>When the board reboots, you are ready for your first reading.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you get stuck flashing the board, ask a mentor — this is a common first hurdle and easy to fix together.</p></div><h3 id="_4-celebrate-your-first-reading" tabindex="-1">4. Celebrate your first reading <a class="header-anchor" href="#_4-celebrate-your-first-reading" aria-label="Permalink to &quot;4. Celebrate your first reading&quot;">​</a></h3><p>Continue with <a href="/AuraLinc-Community/en/docs/tutorials/first-reading">Your first sensor reading</a>.</p><h2 id="next-ideas" tabindex="-1">Next ideas <a class="header-anchor" href="#next-ideas" aria-label="Permalink to &quot;Next ideas&quot;">​</a></h2><ul><li>Try a <a href="/AuraLinc-Community/en/steam/recipes">recipe</a> for a 10-minute activity</li><li>Browse <a href="/AuraLinc-Community/en/steam/examples">examples</a> for project inspiration</li><li>Teachers: see <a href="/AuraLinc-Community/en/steam/">STEAM classroom ideas</a></li></ul>',20)])])}const p=a(i,[["render",n]]);export{m as __pageData,p as default};
